package com.rpb.reservation.workforce;
import java.nio.file.*;import java.util.*;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.assertj.core.api.Assertions.*;
class WorkforceClockOptionsMigrationTest {
 @Test void actual112To113PreservesSingletonsEventsAndFrozenPayroll()throws Exception{
  var pointer=new HashMap<String,String>();for(var l:Files.readAllLines(Path.of("target/local-postgres-current.txt"))){var pair=l.split("=",2);if(pair.length==2)pointer.put(pair[0],pair[1]);}assertThat(Path.of(pointer.get("runtimeWorktree")).toAbsolutePath()).isEqualTo(Path.of("").toAbsolutePath());
  String schema="workforce_options_upgrade_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:postgresql://127.0.0.1:"+Integer.parseInt(pointer.get("port"))+"/postgres?stringtype=unspecified";var root=new JdbcTemplate(new DriverManagerDataSource(url,"postgres",""));var ds=new DriverManagerDataSource(url+"&currentSchema="+schema,"postgres","");var jdbc=new JdbcTemplate(ds);
  try{
   Flyway.configure().dataSource(ds).schemas(schema).defaultSchema(schema).locations("classpath:db/migration").target("112").load().migrate();UUID tenant=UUID.randomUUID(),company=UUID.randomUUID(),store=UUID.randomUUID(),account=UUID.randomUUID(),position=UUID.randomUUID(),employee=UUID.randomUUID(),shift=UUID.randomUUID(),schedule=UUID.randomUUID(),session=UUID.randomUUID();
   jdbc.update("insert into tenants(id,tenant_code,display_name,status) values(?,'MODE-UPGRADE','Mode','active')",tenant);jdbc.update("insert into operating_entities(id,tenant_id,entity_code,display_name,status) values(?,?,'MODE','Mode','active')",company,tenant);jdbc.update("insert into stores(id,tenant_id,operating_entity_id,store_code,display_name,status,timezone,locale,date_format,time_format,currency) values(?,?,?,'MODE','Mode','active','Asia/Singapore','zh-CN','DD-MM-YYYY','HH:mm','SGD')",store,tenant,company);
   jdbc.update("insert into auth_accounts(id,tenant_id,username,display_name,actor_type,status,password_hash) values(?,?,'mode-upgrade','Old','staff','active','unchanged')",account,tenant);jdbc.update("insert into workforce_positions(id,tenant_id,name,version) values(?,?,'Old',1)",position,tenant);
   jdbc.update("insert into workforce_employees(id,tenant_id,employee_no,name,hire_date,status,company_id,company_effective_date,main_store_id,account_id,position_id,version) values(?,?,'OLD','Old','2026-10-01','active',?,'2026-10-01',?,?,?,1)",employee,tenant,company,store,account,position);
   jdbc.update("insert into workforce_shifts(id,tenant_id,store_id,name,snapshot,enabled,version) values(?,?,?,'Old','{}',true,1)",shift,tenant,store);jdbc.update("insert into workforce_schedules(id,tenant_id,store_id,employee_id,company_id,shift_id,work_date,start_at,end_at,timezone,shift_snapshot,status,version) values(?,?,?,?,?,?,'2026-10-28','2026-10-28T01:00:00Z','2026-10-28T09:00:00Z','Asia/Singapore','{}','scheduled',1)",schedule,tenant,store,employee,company,shift);
   jdbc.update("insert into workforce_attendance_sessions(id,tenant_id,store_id,employee_id,schedule_id,in_at,out_at,version) values(?,?,?,?,?,'2026-10-28T01:00:00Z','2026-10-28T09:00:00Z',2)",session,tenant,store,employee,schedule);jdbc.update("insert into workforce_pay_batches(id,tenant_id,company_id,company_name,period_month,status,version,calculation,created_by,confirmed_by,confirmed_at) values(?,?,?,'Old','2026-10-01','confirmed',3,'{\"totalGross\":\"3000.00\"}',?,?,now())",UUID.randomUUID(),tenant,company,account,account);
   UUID assignment=UUID.randomUUID(),event=UUID.randomUUID();
   jdbc.update("update workforce_positions set attendance_mode='onsite' where id=?",position);
   jdbc.update("insert into workforce_work_modes(id,tenant_id,employee_id,effective_from,mode,origin,version) values(?,?,?,'2026-10-28','onsite','personal',1)",assignment,tenant,employee);
   jdbc.update("insert into workforce_clock_events(id,tenant_id,store_id,employee_id,schedule_id,session_id,action,occurred_at,actor_id,response_json) values(?,?,?,?,?,?,'IN','2026-10-28T01:00:00Z',?,'{\"legacy\":true}')",event,tenant,store,employee,schedule,session,account);
   var oldMode=jdbc.queryForObject("select to_jsonb(m)::text from workforce_work_modes m",String.class);var oldEvent=jdbc.queryForObject("select to_jsonb(e)::text from workforce_clock_events e",String.class);
   var oldSession=jdbc.queryForObject("select to_jsonb(s)::text from workforce_attendance_sessions s",String.class);var oldPosition=jdbc.queryForObject("select to_jsonb(p)::text from workforce_positions p",String.class);var oldWage=jdbc.queryForObject("select to_jsonb(p)::text from workforce_pay_batches p",String.class);
   var current=Flyway.configure().dataSource(ds).schemas(schema).defaultSchema(schema).locations("classpath:db/migration").target("113").load();assertThat(current.migrate().migrationsExecuted).isEqualTo(1);assertThat(current.validateWithResult().validationSuccessful).isTrue();assertThat(current.migrate().migrationsExecuted).isZero();
   assertThat(jdbc.queryForObject("select to_jsonb(s)::text from workforce_attendance_sessions s",String.class)).isEqualTo(oldSession);assertThat(jdbc.queryForObject("select (to_jsonb(p)-'attendance_modes')::text from workforce_positions p",String.class)).isEqualTo(oldPosition);assertThat(jdbc.queryForObject("select to_jsonb(p)::text from workforce_pay_batches p",String.class)).isEqualTo(oldWage);assertThat(jdbc.queryForObject("select (to_jsonb(m)-'allowed_modes')::text from workforce_work_modes m",String.class)).isEqualTo(oldMode);assertThat(jdbc.queryForObject("select (to_jsonb(e)-'clock_mode'-'requested_mode')::text from workforce_clock_events e",String.class)).isEqualTo(oldEvent);
   assertThat(jdbc.queryForObject("select allowed_modes is null from workforce_work_modes",Boolean.class)).isTrue();assertThat(jdbc.queryForObject("select attendance_modes is null from workforce_positions where id=?",Boolean.class,position)).isTrue();assertThat(jdbc.queryForObject("select count(*) from workforce_work_mode_commands",Integer.class)).isZero();
   assertThatThrownBy(()->jdbc.update("update workforce_work_modes set allowed_modes=array['onsite','free'] where id=?",assignment)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
   assertThatThrownBy(()->jdbc.update("update workforce_work_modes set allowed_modes=array['onsite','onsite'] where id=?",assignment)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
   assertThatThrownBy(()->jdbc.update("update workforce_work_modes set allowed_modes=array['field'] where id=?",assignment)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
   jdbc.update("update workforce_work_modes set allowed_modes=array['onsite','field'] where id=?",assignment);
   var json=new com.rpb.reservation.workforce.application.WorkforceJson(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules());var resolver=new com.rpb.reservation.workforce.workmode.WorkModeResolver(new com.rpb.reservation.workforce.workmode.WorkModeRepository(jdbc,json));assertThat(resolver.resolve(tenant,employee,store,java.time.LocalDate.of(2026,10,28)).options()).hasSize(2);
assertThat(jdbc.queryForObject("select count(*) from workforce_home_addresses",Integer.class)).isZero();
  }finally{if(schema.matches("workforce_options_upgrade_[a-f0-9]{32}"))root.execute("drop schema if exists "+schema+" cascade");}
 }
}
